const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={search:'<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>',admin:'<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/></svg>',bookmark:'<svg width="12" height="15" viewBox="0 0 16 20" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M3 2h10v15l-5-3-5 3Z"/></svg>'};
let original=await fetch('movies.json').then(r=>r.json()); const archivePromise=fetch('archive.json').then(r=>r.ok?r.json():[]).catch(()=>[]);const albumsPromise=fetch('albums.json').then(r=>r.ok?r.json():[]).catch(()=>[]);let archiveLoaded=false,albumsLoaded=false,albums=[];const snapshot=await fetch('catalog-report.json').then(r=>r.json()).catch(()=>({}));let movies=[...original,...read('cineclay.custom',[])],saved=read('cineclay.saved',[]),reviews=read('cineclay.reviews',{}),page='discover',tab='catalog',query='',year='',genre='',decade='',sort='curated',limit=12,region=read('cineclay.region','IN');let catalogPage=1,pageSize=12,mediaType='',activeHero=0,heroMode='all',adminPage=1,adminQuery='',language='',slidesPaused=false,musicQuery='',musicLanguage='',musicYear='',musicPage=1,musicPlayable=false;let clayDot;const platforms=await fetch('platforms.json').then(r=>r.json());
function read(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('Storage unavailable. Changes will last for this session.')}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2800)}
const genres=['All genres',...new Set([...original.flatMap(m=>m.genres||[]),'Action','Adventure','Animation','Biography','Comedy','Crime','Documentary','Drama','Family','Fantasy','History','Horror','Music','Mystery','Romance','Science Fiction','Sport','Thriller','War','Western','Anime','Legal','Medical','Espionage','Supernatural'].filter(g=>g!=='Uncategorized'))].sort((a,b)=>a==='All genres'?-1:b==='All genres'?1:a.localeCompare(b));
function baseHeader(){return `<header><a class="brand" href="#" aria-label="Cineclay home"><b>c</b>cineclay<em>.</em></a><nav aria-label="Main navigation">${[['discover','Discover'],['albums','Albums'],['reviews','Reviews'],['watchlist',`Watchlist <small>${saved.length||''}</small>`]].map(([p,n])=>`<button data-page="${p}" class="${page===p?'active':''}">${n}</button>`).join('')}</nav><div class="tools"><label class="region">◎ <select id="region" aria-label="Streaming region"><option value="IN" ${region==='IN'?'selected':''}>India</option><option value="US" ${region==='US'?'selected':''}>United States</option><option value="GB" ${region==='GB'?'selected':''}>United Kingdom</option></select></label><button class="theme-toggle" data-theme-toggle aria-label="Toggle color theme" title="Toggle color theme"><span aria-hidden="true">☾</span></button><a class="signout" href="/signout-with-chatgpt?return_to=%2F" target="_top" aria-label="Sign out">↗ <span>Sign out</span></a></div></header>`}
function footer(){return `<footer><a class="brand" href="#">cineclay.</a><span>A little curiosity. A great film.</span><div class="foot-links"><button class="chip" id="about">About & data</button><span class="demo-label">Wikipedia · TVmaze · Curated films</span><span>© ${new Date().getFullYear()} Cineclay</span></div></footer>`}
function render(){ $('#app').innerHTML=`<div class="shell">${header()}<main>${page==='admin'?admin():page==='reviews'?reviewPage():page==='albums'?albumsPage():discover()}</main>${footer()}</div>`; bind();window.cineclayTheme?.sync();if(page==='albums')filterAlbums();else if(page!=='admin'&&page!=='reviews')filter(); }
function baseDiscover(){return `${page==='discover'?`<div class="intro"><div><span class="eyebrow">For the love of cinema</span><h1>Your next great film starts here.</h1></div><p>Extraordinary stories. Every era. One place.</p></div><section class="hero-grid" aria-label="Featured films"><article class="hero"><img src="hero.jpg" alt="Paul Atreides and Chani against the sunlit dunes of Arrakis"><div class="hero-content"><span class="hero-tag"><span>✦</span> THE SPOTLIGHT</span><div class="hero-bottom"><div class="meta"><span class="score">★ 8.5</span><span>2024</span><span>2h 45m</span><span>Science fiction · Adventure</span></div><h2>Dune: Part Two</h2><p>Destiny is written in the sand. Enter Denis Villeneuve’s breathtaking vision of a world on the edge of change.</p><div class="hero-buttons"><button class="primary" data-detail="693134">Explore the film &nbsp; ↗</button><button class="glass" data-trailer="693134">▷ &nbsp; Watch trailer</button></div></div><div class="slide-count" aria-hidden="true"><i></i><i></i><i></i></div></div></article><aside class="editorial"><span class="eyebrow">The cineclay collection</span><div class="orb"></div><div class="clay">✧</div><h2>Great stories.<br>Timeless cinema.</h2><p>From ’90s icons to modern masterpieces. Rediscover the films that stay with you.</p><button id="classics">Explore the classics <span>↗</span></button></aside></section>`:''}<section id="catalog"><div class="catalog-head"><div><h2>${page==='watchlist'?'Your personal watchlist':'Find your kind of cinema'}</h2><p>${page==='watchlist'?'A home for the films you want to see.':'A whole world of stories, waiting to be discovered.'}</p></div><span class="count" id="result-count"></span></div><div class="filters"><label class="search">${icons.search}<input id="search" type="search" placeholder="Search movies, actors, directors…" value="${esc(query)}" aria-label="Search movies, cast and directors"></label><select id="year" aria-label="Release year"><option value="">All years</option>${Array.from({length:new Date().getFullYear()+11-1990},(_,i)=>new Date().getFullYear()+10-i).map(y=>`<option ${String(y)===year?'selected':''}>${y}</option>`).join('')}</select><select id="genre-select" aria-label="Genre">${genres.map(g=>`<option value="${g==='All genres'?'':g}" ${genre===g?'selected':''}>${g}</option>`).join('')}</select><div class="sort"><span>Sort by:</span><select id="sort" aria-label="Sort movies"><option value="curated">Curated for you</option><option value="new">Newest first</option><option value="old">Oldest first</option><option value="rating">Highest demo score</option><option value="title">Title A–Z</option></select></div></div><div class="genre-tabs" aria-label="Quick genre filters">${['','Science Fiction','Drama','Thriller','Action','Comedy','Romance','Animation'].map(g=>`<button data-genre="${g}" class="chip ${genre===g?'active':''}">${g||'✦ All movies'}</button>`).join('')}<button class="chip" id="clear">Reset filters ↺</button></div><div class="movie-grid" id="movie-grid"></div><div class="load-row" id="load-row"></div></section>${page==='discover'?`<section><div class="section-line"><h2>A journey through the decades</h2><button id="all-years">Every era has a story ↗</button></div><div class="decades">${[['1990','The unforgettable ’90s','◈'],['2000','A new millennium','◎'],['2010','A decade of discovery','✳'],['2020','The stories of now','✧']].map(([d,t,s])=>`<button class="decade" data-decade="${d}"><div><strong>${d}s</strong><span>${t}</span></div><i>${s}</i></button>`).join('')}</div></section>`:''}`}
function searchText(value){return String(value??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase()}
function baseFiltered(){const needle=searchText(query.trim());let a=movies.filter(m=>(page!=='watchlist'||saved.includes(m.id))&&(!year||m.year===+year)&&(!genre||m.genres.includes(genre))&&(!decade||m.year>=+decade&&m.year<+decade+10)&&(!needle||searchText([m.title,m.summary,m.director,m.source,...m.cast,...m.genres,...(m.languages||[])].join(' ')).includes(needle)));return sort==='new'?a.sort((a,b)=>b.year-a.year):sort==='old'?a.sort((a,b)=>a.year-b.year):sort==='title'?a.sort((a,b)=>a.title.localeCompare(b.title)):sort==='rating'?a.sort((a,b)=>(b.score||0)-(a.score||0)):a}
function baseCard(m){return `<article class="movie-card"><div class="poster-wrap" data-detail="${m.id}" role="button" tabindex="0" aria-label="Explore ${esc(m.title)}">${m.poster?`<img src="${esc(m.poster)}" alt="${esc(m.title)} theatrical poster" loading="lazy" onerror="this.hidden=true;this.nextElementSibling.style.display='block'">`:''}<span class="poster-title" style="${m.poster?'':'display:block'}">${esc(m.title)}</span>${m.score&&m.source==='TVmaze'?`<span class="rating-badge" title="Sample catalog score">★ ${m.score.toFixed(1)}</span>`:''}<button class="bookmark ${saved.includes(m.id)?'saved':''}" data-save="${m.id}" aria-label="${saved.includes(m.id)?'Remove from':'Add to'} watchlist" aria-pressed="${saved.includes(m.id)}">${icons.bookmark}</button></div><h3><button data-detail="${m.id}">${esc(m.title)}</button></h3><div class="card-meta"><span>${m.year}</span><span>·</span><span>${esc(m.genres[0]==='Science Fiction'?'Sci-Fi':m.genres[0])}</span></div><div class="platforms">${m.providers.some(p=>(p.region===region||p.region==='GLOBAL'))?m.providers.filter(p=>(p.region===region||p.region==='GLOBAL')).map(p=>`<span class="provider">${esc(p.name)}</span>`).join(''):'<span>◎ &nbsp; Find where to watch</span>'}</div></article>`}
function filter(){const a=filtered();catalogPage=Math.min(Math.max(1,catalogPage),Math.max(1,Math.ceil(a.length/pageSize)));const start=(catalogPage-1)*pageSize;$('#result-count').textContent=`${a.length.toLocaleString()} title${a.length===1?'':'s'}${decade?' · '+decade+'s':''}${archiveLoaded?'':' · full archive loading…'}`;$('#movie-grid').innerHTML=a.length?a.slice(start,start+pageSize).map(card).join(''):`<div class="empty"><h3>${page==='watchlist'&&!saved.length?'Your next movie night starts here.':'No titles match these filters.'}</h3><p>Try another year, genre, or media type. Archive coverage and metadata vary by source.</p><button class="primary" id="reset-empty">Reset filters</button></div>`;const pages=Math.ceil(a.length/pageSize);const nums=[...new Set([1,catalogPage-1,catalogPage,catalogPage+1,pages])].filter(n=>n>0&&n<=pages).sort((a,b)=>a-b);$('#load-row').innerHTML=pages?`<div class="pagination"><span>Showing ${(start+1).toLocaleString()}–${Math.min(start+pageSize,a.length).toLocaleString()} of ${a.length.toLocaleString()} titles</span><div class="page-controls"><button data-pg="${catalogPage-1}" ${catalogPage===1?'disabled':''} aria-label="Previous page">←</button>${nums.map((n,i)=>`${i&&n-nums[i-1]>1?'<span>…</span>':''}<button data-pg="${n}" class="${n===catalogPage?'current':''}" ${n===catalogPage?'aria-current="page"':''}>${n}</button>`).join('')}<button data-pg="${catalogPage+1}" ${catalogPage===pages?'disabled':''} aria-label="Next page">→</button></div><label>Per page <select id="page-size" aria-label="Titles per page">${[12,24,48].map(n=>`<option ${n===pageSize?'selected':''}>${n}</option>`).join('')}</select></label></div>`:'';bindCards();document.querySelectorAll('[data-pg]').forEach(b=>b.onclick=()=>{catalogPage=+b.dataset.pg;filter();scrollCatalog()});$('#page-size')?.addEventListener('change',e=>{pageSize=+e.target.value;catalogPage=1;filter()});$('#reset-empty')?.addEventListener('click',()=>{if(page==='watchlist')page='discover';reset();render()})}
function reset(){query='';year='';genre='';decade='';sort='curated';catalogPage=1;mediaType='';language='';limit=12}function scrollCatalog(){requestAnimationFrame(()=>$('#catalog')?.scrollIntoView({behavior:'smooth',block:'start'}))}
function baseBind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;reset();render();window.scrollTo(0,0)});$('.brand').onclick=e=>{e.preventDefault();page='discover';reset();render()};$('#region')?.addEventListener('change',e=>{region=e.target.value;persist('cineclay.region',region);render()});$('#about').onclick=()=>show(`<div class="modal-header"><b>About Cineclay</b><button class="close" aria-label="Close">×</button></div><div style="padding:26px;line-height:1.8"><p>An independent discovery space for people who love film, television and music, from Hollywood and Bollywood to the stories of Odisha.</p><p>Our catalog combines curated titles with public Wikipedia release lists, TVmaze and MusicBrainz. Coverage varies, and missing details are marked.</p><p>Your watchlist and reviews are stored on this device. Artwork and trailers belong to their respective owners.</p></div>`);if(page==='admin'){bindAdmin();return}if(page==='reviews'){bindCards();return}if(page==='albums')return;$('#search').oninput=e=>{query=e.target.value;limit=12;filter()};$('#year').onchange=e=>{year=e.target.value;decade='';limit=12;filter()};$('#genre-select').onchange=e=>{genre=e.target.value;render()};$('#sort').value=sort;$('#sort').onchange=e=>{sort=e.target.value;filter()};document.querySelectorAll('[data-genre]').forEach(b=>b.onclick=()=>{genre=b.dataset.genre;render()});$('#clear').onclick=()=>{reset();render()};$('#classics')?.addEventListener('click',()=>{decade='1990';year='';render();scrollCatalog()});document.querySelectorAll('[data-decade]').forEach(b=>b.onclick=()=>{reset();decade=b.dataset.decade;render();scrollCatalog()});$('#all-years')?.addEventListener('click',()=>{reset();render();scrollCatalog()});bindCards()}
function bindCards(){document.querySelectorAll('[data-detail]').forEach(b=>{b.onclick=()=>detail(+b.dataset.detail);if(b.classList.contains('poster-wrap'))b.onkeydown=e=>{if(e.key==='Enter')detail(+b.dataset.detail)}});document.querySelectorAll('[data-save]').forEach(b=>b.onclick=e=>{e.stopPropagation();const id=+b.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist('cineclay.saved',saved);toast(saved.includes(id)?'Added to your watchlist':'Removed from watchlist');render()});document.querySelectorAll('[data-trailer]').forEach(b=>b.onclick=()=>trailer(+b.dataset.trailer))}
function show(html){const d=$('#details');d.innerHTML=html;if(!d.open)d.showModal();d.querySelector('.close').onclick=()=>d.close();d.onclick=e=>{if(e.target===d)d.close()}}
function detail(id){const m=movies.find(m=>m.id===id);if(!m)return;const providers=m.providers.filter(p=>(p.region===region||p.region==='GLOBAL'));show(`<div class="modal-header"><span class="eyebrow">The film journal</span><button class="close" aria-label="Close">×</button></div><div class="modal-body">${m.poster?`<img src="${esc(m.poster)}" alt="${esc(m.title)} poster">`:'<div></div>'}<div><h2>${esc(m.title)}</h2><div class="detail-meta">${m.mediaType==='tv'?'TV SERIES':'MOVIE'} · ${m.year} · ${esc((m.languages||[]).join(' / ')||'Language not indexed')} · ${m.runtime?`${m.runtime} min · `:''}${esc(m.genres.join(' / '))}</div><p>${esc(m.summary)}</p>${m.sourceUrl?`<a class="source-link" href="${esc(m.sourceUrl)}" target="_blank" rel="noopener">${esc(m.source)} source ↗</a>`:''}<div class="detail-section">Directed by</div><p>${esc(m.director||'Not indexed')}</p><div class="detail-section">Starring · Actors & actresses</div><div class="cast">${m.cast.map(c=>`<span>${esc(c)}</span>`).join('')}</div><div class="detail-section">Where to watch · ${region}</div><button class="dot-inline" data-ask-watch="${m.id}">✦ Ask clayDot about this title</button>${providers.length?providers.map(p=>`<a class="watch-link" href="${esc(p.url)}" target="_blank" rel="noopener">${providerLogo(p.name)} ${esc(p.name)} &nbsp; ↗</a>`).join(''):`<a class="watch-link" href="https://www.justwatch.com/${region==='IN'?'in':region==='GB'?'uk':'us'}/search?q=${encodeURIComponent(m.title)}" target="_blank" rel="noopener">Check availability on JustWatch ↗</a>`}<p class="note">${providers.length?'Official title/provider link last checked '+esc(providers[0].checkedAt||'date not recorded')+'. Official title pages do not confirm a subscription offer in your region. Check local availability before subscribing.':'Live availability has not been imported for this film. This link opens a search, not a verified streaming offer.'}</p>${m.trailer?`<button class="primary" id="play-trailer">▷ Watch trailer</button>`:''}<div class="review-box"><b>Your review</b><p class="note">Your own words, saved on this device.</p><form id="review-form"><select name="rating" aria-label="Your rating">${[5,4,3,2,1].map(n=>`<option value="${n}">${'★'.repeat(n)}</option>`).join('')}</select><textarea name="text" aria-label="Review" required maxlength="2000" placeholder="What stayed with you?"></textarea><button class="primary">Save review</button></form>${(reviews[id]||[]).map(r=>`<div class="review-item"><b>${'★'.repeat(r.rating)} · Your review</b>${esc(r.text)}</div>`).join('')}</div></div></div>`);bindWatch();$('#play-trailer')?.addEventListener('click',()=>trailer(id));$('#review-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);reviews[id]=[{rating:+f.get('rating'),text:f.get('text').trim()},...(reviews[id]||[])];persist('cineclay.reviews',reviews);detail(id);toast('Your review is saved')}}
function trailer(id){const m=movies.find(x=>x.id===id);if(!m?.trailer){toast('No verified trailer is available for this title yet');return}show(`<div class="modal-header"><b>${esc(m.title)} · Official trailer</b><button class="close" aria-label="Close">×</button></div><iframe class="trailer-frame" src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(m.trailer)}" title="${esc(m.title)} trailer" allow="autoplay; encrypted-media; fullscreen" allowfullscreen></iframe><p style="padding:0 22px 15px;font-size:12px"><a href="https://www.youtube.com/watch?v=${encodeURIComponent(m.trailer)}" target="_blank" rel="noopener">Open trailer on YouTube ↗</a></p>`);$('#details').addEventListener('close',()=>{$('#details').innerHTML=''}, {once:true})}
function reviewPage(){let list=Object.entries(reviews).flatMap(([id,rs])=>rs.map(r=>({...r,m:movies.find(m=>m.id===+id)}))).filter(r=>r.m);return `<section class="review-page"><span class="eyebrow">The film journal</span><h1>Stories worth talking about.</h1><p style="color:#8a927f">Your reviews, collected in one place.</p>${list.length?list.map(r=>`<article class="review-item"><b>${'★'.repeat(r.rating)}</b><h3><button class="chip" data-detail="${r.m.id}">${esc(r.m.title)} ↗</button></h3>${esc(r.text)}</article>`).join(''):'<div class="empty"><h3>Your perspective belongs here.</h3><p>Open a film and write your first review. It will appear in your personal journal.</p></div>'}</section>`}
function admin(){return `<div class="admin-intro"><div><span class="eyebrow">Cineclay studio</span><h1>Make room for more stories.</h1><p>Manage your movie catalog, artwork and watch links.</p></div><button class="primary" id="new-movie">＋ Add a film</button></div><div class="notice">Preview workspace · Changes are stored on this device. The included Blazor application connects to PostgreSQL; automatic imports require a server-side TMDB token.</div><div class="stats"><div class="stat"><span>Catalog titles</span><strong>${movies.length}</strong></div><div class="stat"><span>Years represented</span><strong>${new Set(movies.map(m=>m.year)).size}</strong></div><div class="stat"><span>Genres to discover</span><strong>${new Set(movies.flatMap(m=>m.genres)).size}</strong></div><div class="stat"><span>Saved to watchlist</span><strong>${saved.length}</strong></div></div><div class="admin-tabs">${[['catalog','Film library'],['add','Manual entry'],['import','Import from TMDB'],['settings','Data & export']].map(([t,n])=>`<button class="${tab===t?'active':''}" data-tab="${t}">${n}</button>`).join('')}</div><div id="admin-content">${tab==='catalog'?adminTable():tab==='add'?movieForm():tab==='import'?`<section class="form-panel"><h2>Bring the world of cinema in.</h2><p>Import official metadata, posters, credits, trailers and regional watch providers through TMDB. The .NET API stores credentials securely on the server.</p><div class="notice">Not connected in this hosted preview. Run the included .NET application, set <code>TMDB_TOKEN</code>, and use its authenticated import dashboard. No API credential is saved in your browser.</div><p>Import a film by its TMDB ID, or import a page of releases for any year from 1990 onward. Imports update matching IDs without duplicating films.</p><a class="watch-link" href="https://www.themoviedb.org/settings/api" target="_blank" rel="noopener">Get a TMDB API credential ↗</a></section>`:`<section class="form-panel"><h2>Your catalog, your data.</h2><p>Download this preview’s catalog as JSON. In the .NET application, records live in PostgreSQL. To move to Supabase, restore the database and change the connection string to its PostgreSQL endpoint.</p><button class="primary" id="export">Export catalog JSON ↓</button><p style="margin-top:24px"><a class="watch-link" href="Cineclay.Source.zip" download>Download .NET 10 application source ↓</a></p><p class="note">No cloud database is connected to this preview.</p></section>`}</div>`}
function baseAdminTable(){return `<div class="table-wrap"><table><thead><tr><th>Film title</th><th>Year</th><th>Genre</th><th>Source</th><th>Actions</th></tr></thead><tbody>${movies.map(m=>`<tr><td>${esc(m.title)}</td><td>${m.year}</td><td>${esc(m.genres[0])}</td><td><span class="pill">${m.source==='Manual'?'Manual':'Curated sample'}</span></td><td><button data-edit="${m.id}">Edit</button><button data-delete="${m.id}">Remove</button></td></tr>`).join('')}</tbody></table></div>`}
function movieForm(m={}){return `<section class="form-panel"><h2>${m.id?'Edit this film':'Add a new story.'}</h2><p>A little detail makes every discovery better. Required fields are marked *.</p><form id="movie-form" data-id="${m.id||''}"><div class="form-grid"><label>Movie title *<input name="title" required maxlength="200" value="${esc(m.title||'')}"></label><label>Content type<select name="mediaType"><option value="movie" ${m.mediaType!=='tv'?'selected':''}>Movie</option><option value="tv" ${m.mediaType==='tv'?'selected':''}>TV series</option></select></label><label>Release year *<input name="year" type="number" min="1990" max="9999" required value="${m.year||2026}"></label><label>Genres * (comma separated)<input name="genres" required value="${esc(m.genres?.join(', ')||'')}"></label><label>Original language(s)<input name="languages" value="${esc((m.languages||[]).join(', '))}" placeholder="English, Hindi…"></label><label>Director<input name="director" value="${esc(m.director||'')}"></label><label class="full">Actors & actresses * (comma separated)<input name="cast" required value="${esc(m.cast?.join(', ')||'')}"></label><label class="full">Summary *<textarea name="summary" required maxlength="5000">${esc(m.summary||'')}</textarea></label><label>Poster URL (HTTPS)<input name="poster" type="url" pattern="https://.*" value="${m.poster?.startsWith('https:')?esc(m.poster):''}"></label><label>Runtime in minutes<input name="runtime" type="number" min="1" max="1500" value="${m.runtime||''}"></label><label>YouTube trailer video ID<input name="trailer" pattern="[a-zA-Z0-9_-]{11}" value="${esc(m.trailer||'')}" placeholder="11 character video ID"></label><label>OTT platform name<input name="platform" value="${esc(m.providers?.[0]?.name||'')}"></label><label>Direct OTT URL (HTTPS)<input name="url" type="url" pattern="https://.*" value="${esc(m.providers?.[0]?.url||'')}"></label><label>Watch region<select name="region"><option>IN</option><option>US</option><option>GB</option></select></label></div><button class="primary">Save film &nbsp; ↗</button></form></section>`}
function saveCustom(){const originals=new Map(original.map(m=>[m.id,m]));const current=new Set(movies.map(m=>m.id));persist('cineclay.custom',movies.filter(m=>!originals.has(m.id)));persist('cineclay.overrides',movies.filter(m=>originals.has(m.id)&&JSON.stringify(m)!==JSON.stringify(originals.get(m.id))));persist('cineclay.removed',original.filter(m=>!current.has(m.id)).map(m=>m.id))}
function baseBindAdmin(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});$('#new-movie').onclick=()=>{tab='add';render()};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{tab='add';render();$('#admin-content').innerHTML=movieForm(movies.find(m=>m.id===+b.dataset.edit));bindForm()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const id=+b.dataset.delete,m=movies.find(m=>m.id===id);show(`<div class="modal-header"><b>Remove film?</b><button class="close">×</button></div><div style="padding:26px"><p>Remove ${esc(m.title)} from this preview catalog?</p><button class="primary" id="confirm-delete">Remove film</button></div>`);$('#confirm-delete').onclick=()=>{movies=movies.filter(m=>m.id!==id);saveCustom();$('#details').close();render();toast('Film removed')}});$('#export')?.addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(movies,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='cineclay-catalog.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});bindForm()}
function bindForm(){const f=$('#movie-form');if(!f)return;f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));if((d.platform&&!d.url)||(d.url&&!d.platform)){toast('Add both a platform name and its URL');return}const id=+f.dataset.id||Date.now();const old=movies.find(m=>m.id===id);const m={...old,id,mediaType:d.mediaType||'movie',languages:(d.languages||'').split(',').map(x=>x.trim()).filter(Boolean),title:d.title.trim(),year:+d.year,genres:d.genres.split(',').map(x=>x.trim()).filter(Boolean),cast:d.cast.split(',').map(x=>x.trim()).filter(Boolean),director:d.director,summary:d.summary.trim(),runtime:+d.runtime||null,poster:d.poster||old?.poster||'',trailer:d.trailer,score:old?.score||null,providers:d.url?[{name:d.platform,url:d.url,region:d.region,checkedAt:new Date().toISOString().slice(0,10),type:'manual'}]:[],source:'Manual'};movies=movies.some(m=>m.id===id)?movies.map(x=>x.id===id?m:x):[m,...movies];saveCustom();tab='catalog';render();toast('Film saved to your catalog')}}

function header(){return baseHeader().replace('<b>c</b>','<b class="brand-mark"><img src="logos/cineclay.svg" alt=""/></b>')}
function filtered(){return baseFiltered().filter(m=>(!mediaType||(m.mediaType||'movie')===mediaType)&&(!language||language==='__unknown__'?(language!=='__unknown__'||!(m.languages||[]).length):(m.languages||[]).includes(language)))}
function oldProviderLogo(name){const key=/netflix/i.test(name)?'netflix':/amazon|prime/i.test(name)?'primevideo':/apple/i.test(name)?'appletv':/disney/i.test(name)?'disneyplus':/max|hbo/i.test(name)?'hbomax':/peacock/i.test(name)?'peacock':'';return key?`<img class="ott-logo" src="logos/${key}.${['hulu','hbomax'].includes(key)?'svg':'ico'}" alt="${esc(name)} logo" onerror="this.hidden=true">`:'<span aria-hidden="true">▷</span>'}
function offers(m){return m.providers.filter(p=>p.region===region||p.region==='GLOBAL')}
function card(m){let html=baseCard(m);html=html.replace('<span>'+m.year+'</span>',`<span>${m.year}</span><span>·</span><span>${m.mediaType==='tv'?'TV':'Film'}</span>`);html=html.replace(/<div class="platforms">.*?<\/div>/,`<div class="platforms">${offers(m).length?offers(m).slice(0,2).map(p=>`<a class="platform-icon" href="${esc(p.url)}" target="_blank" rel="noopener" title="${esc(p.name)} · ${p.type==='official-title'?'Official title page':'Provider link'}">${providerLogo(p.name)}<span>${esc(p.name)}</span></a>`).join(''):`<button class="ask-watch" data-ask-watch="${m.id}">◎ Find where to watch</button>`}</div>`);return html}
function heroTitles(){const a=movies.filter(m=>m.poster&&m.metadataStatus!=='index-only'&&(!heroMode||heroMode==='all'||m.mediaType===heroMode));return a.sort((a,b)=>b.year-a.year||(b.score||0)-(a.score||0)).slice(0,20)}
function heroMarkup(){const top=heroTitles();activeHero=Math.min(activeHero,top.length-1);const m=top[activeHero];if(!m)return '';return `<div class="hero-content"><span class="hero-tag"><span>✦</span> TOP 20 · LATEST IN THIS CATALOG</span><div class="hero-bottom"><div class="meta"><span class="hero-rank">#${String(activeHero+1).padStart(2,'0')}</span><span>${m.mediaType==='tv'?'TV SERIES':'MOVIE'}</span><span>${m.year}</span><span>${esc(m.genres.slice(0,2).join(' · '))}</span></div><h2>${esc(m.title)}</h2><p>${esc(m.summary.length>180?m.summary.slice(0,177)+'…':m.summary)}</p><div class="hero-buttons"><button class="primary" data-detail="${m.id}">Explore ${m.mediaType==='tv'?'series':'film'} &nbsp; ↗</button>${m.trailer?`<button class="glass" data-trailer="${m.id}">▷ &nbsp; Watch trailer</button>`:''}${offers(m)[0]?`<a class="glass hero-watch" href="${esc(offers(m)[0].url)}" target="_blank" rel="noopener">${providerLogo(offers(m)[0].name)} Official watch page ↗</a>`:''}</div></div><div class="hero-navigation"><button id="hero-toggle" aria-label="${slidesPaused?'Play slideshow':'Pause slideshow'}">${slidesPaused?'▷':'Ⅱ'}</button><button id="hero-prev" aria-label="Previous featured title">←</button><span>${String(activeHero+1).padStart(2,'0')} / ${top.length}</span><button id="hero-next" aria-label="Next featured title">→</button></div></div>`}
function heroPanel(){const top=heroTitles();const m=top[activeHero];return `<section class="hero-grid" aria-label="Top 20 latest catalog titles"><article class="hero dynamic-hero"><img src="${m?.id===693134?'hero.jpg':esc(m?.poster||'hero.jpg')}" alt="${esc(m?.title||'Cinema')} promotional artwork">${heroMarkup()}</article><aside class="top-ten-panel"><div class="top-ten-head"><span class="eyebrow">The latest edit</span><h2>Twenty stories.<br>One perfect next watch.</h2><div class="hero-type-tabs">${[['all','All'],['movie','Films'],['tv','Series']].map(([v,t])=>`<button data-hero-mode="${v}" class="${heroMode===v?'active':''}">${t}</button>`).join('')}</div></div><div class="top-ten-list">${top.map((m,i)=>`<button data-hero="${i}" class="${i===activeHero?'active':''}"><span>${String(i+1).padStart(2,'0')}</span><img src="${esc(m.poster)}" alt=""><div><strong>${esc(m.title)}</strong><small>${m.year} · ${m.mediaType==='tv'?'TV series':'Movie'}</small></div><i>↗</i></button>`).join('')}</div><p class="note">Newest premiere years in our enriched catalog. Not a global streaming chart.</p></aside></section>`}
function extendedDiscover(){let html=baseDiscover();const filmCount=archiveLoaded?movies.filter(m=>(m.mediaType||'movie')==='movie').length:(snapshot.movies||movies.filter(m=>(m.mediaType||'movie')==='movie').length),tvCount=movies.filter(m=>m.mediaType==='tv').length;html=html.replace('Your next great film starts here.','Your next great story starts here.').replace('Extraordinary stories. Every era. One place.','Movies. Series. Every era. One place.');html=html.replace(/<section class="hero-grid"[\s\S]*?<\/section>/,heroPanel());const totals=`<section class="catalog-totals" aria-label="Catalog totals"><div><strong>${filmCount.toLocaleString()}</strong><span>Movies indexed</span></div><div><strong>${tvCount.toLocaleString()}</strong><span>TV series</span></div><div><strong>1990–${new Date().getFullYear()}</strong><span>Archive years · future filters supported</span></div><div><strong>${new Set(movies.flatMap(m=>m.genres).filter(g=>g!=='Uncategorized')).size}</strong><span>Genres</span></div><p>Public Wikipedia release lists + TVmaze. Missing metadata is marked.</p></section>`;html=html.replace('<section id="catalog">',totals+'<section id="catalog">');html=html.replace('<div class="genre-tabs"',`<div class="media-tabs" role="group" aria-label="Content type">${[['','All titles'],['movie','Movies'],['tv','TV series']].map(([v,t])=>`<button data-media="${v}" class="${mediaType===v?'active':''}">${t}</button>`).join('')}</div><div class="genre-tabs"`);return html}
function baseExtendedBind(){baseBind();document.querySelectorAll('[data-media]').forEach(b=>b.onclick=()=>{mediaType=b.dataset.media;catalogPage=1;render()});document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{activeHero=+b.dataset.hero;render()});document.querySelectorAll('[data-hero-mode]').forEach(b=>b.onclick=()=>{heroMode=b.dataset.heroMode;activeHero=0;render()});$('#hero-next')?.addEventListener('click',()=>{activeHero=(activeHero+1)%heroTitles().length;render()});$('#hero-prev')?.addEventListener('click',()=>{activeHero=(activeHero+heroTitles().length-1)%heroTitles().length;render()});for(const selector of ['#search','#year','#genre-select','#sort'])$(selector)?.addEventListener(selector==='#search'?'input':'change',()=>{catalogPage=1;filter()});document.querySelectorAll('[data-genre]').forEach(b=>b.addEventListener('click',()=>{catalogPage=1;filter()}));}
function adminTable(){const entries=movies.filter(m=>!adminQuery||[m.title,m.year,...m.cast].join(' ').toLowerCase().includes(adminQuery.toLowerCase()));const pages=Math.max(1,Math.ceil(entries.length/50));adminPage=Math.min(Math.max(adminPage,1),pages);return `<form id="admin-find" class="filters"><label class="search"><input name="q" aria-label="Search full Studio catalog" value="${esc(adminQuery)}" placeholder="Search all catalog records…"></label><button class="primary">Search library</button></form><div class="table-wrap"><table><thead><tr><th>Title</th><th>Year</th><th>Type</th><th>Source</th><th>Actions</th></tr></thead><tbody>${entries.slice((adminPage-1)*50,adminPage*50).map(m=>`<tr><td>${esc(m.title)}</td><td>${m.year}</td><td>${m.mediaType==='tv'?'TV':'Movie'}</td><td>${esc(m.source)}</td><td><button data-edit="${m.id}">Edit</button><button data-delete="${m.id}">Remove</button></td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>${entries.length.toLocaleString()} records · Page ${adminPage} of ${pages}</span><div class="page-controls"><button id="admin-prev" ${adminPage===1?'disabled':''}>← Previous</button><button class="current" aria-current="page">${adminPage}</button><button id="admin-next" ${adminPage===pages?'disabled':''}>Next →</button></div></div>`}
function bindAdmin(){baseBindAdmin();$('#admin-find')?.addEventListener('submit',e=>{e.preventDefault();adminQuery=new FormData(e.target).get('q');adminPage=1;render()});$('#admin-prev')?.addEventListener('click',()=>{adminPage--;render()});$('#admin-next')?.addEventListener('click',()=>{adminPage++;render()})}
function splash(){
 if(sessionStorage.getItem('cineclay.entered'))return;
 const slides=[{name:'Hollywood',subtitle:'Epic worlds. Endless imagination.',id:693134,video:'Way9Dexny3w',art:'hero.jpg'},{name:'Bollywood',subtitle:'Big emotions. Unforgettable stories.',id:274656132998611,video:'COv52Qyctws',art:'https://images.herzindagi.info/image/2024/Jul/jawan-cast.jpg'},{name:'Ollywood',subtitle:'Rooted in Odisha. Made for the world.',id:610000000002,video:'E_p4kHzZBTM',art:'https://m.media-amazon.com/images/M/MV5BN2U0ZjJiNWUtM2M5Ni00ZDEzLWFlMTAtZWU2ZWQyZTY5MGYwXkEyXkFqcGc%40._V1_.jpg'}];
 const overlay=document.createElement('section');overlay.className='cinema-splash industry-splash';overlay.setAttribute('aria-label','Welcome to Cineclay');overlay.innerHTML=`<div class="splash-backdrop"></div><div class="splash-video"></div><div class="splash-grain"></div><div class="splash-inner"><img class="splash-logo" src="logos/cineclay.svg" alt="Cineclay"><span class="eyebrow">A WORLD OF CINEMA · THREE SPOTLIGHTS</span><h1 class="industry-name"></h1><p class="industry-subtitle"></p><div class="splash-actions"><button class="primary" id="enter-cinema">Enter Cineclay ↗</button><button class="splash-trailer" id="splash-trailer">▷ Watch the trailer</button></div><span class="splash-note">Trailer previews play muted. Availability may vary.</span><div class="splash-industries" aria-label="Choose cinema spotlight">${slides.map((x,i)=>`<button data-industry="${i}">${x.name}</button>`).join('')}</div></div><button class="skip-splash" id="skip-splash">Skip intro ×</button>`;document.body.append(overlay);
 let index=0,closed=false,timer;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches||navigator.connection?.saveData;
 function draw(){const x=slides[index];overlay.querySelector('.splash-backdrop').style.backgroundImage=`linear-gradient(90deg,rgba(9,16,13,.98),rgba(9,16,13,.15)),url("${x.art}")`;overlay.querySelector('.industry-name').textContent=x.name+'.';overlay.querySelector('.industry-subtitle').textContent=x.subtitle;overlay.querySelectorAll('[data-industry]').forEach((b,i)=>b.classList.toggle('active',i===index));overlay.querySelector('.splash-video').innerHTML=reduced?'':`<iframe title="${x.name} trailer preview (muted)" src="https://www.youtube-nocookie.com/embed/${x.video}?autoplay=1&mute=1&controls=0&playsinline=1&rel=0" allow="autoplay; encrypted-media" tabindex="-1"></iframe>`}
 function close(){if(closed)return;closed=true;clearInterval(timer);sessionStorage.setItem('cineclay.entered','1');overlay.querySelector('.splash-video').innerHTML='';overlay.classList.add('leaving');setTimeout(()=>overlay.remove(),500)}
 overlay.querySelector('#enter-cinema').onclick=close;overlay.querySelector('#skip-splash').onclick=close;overlay.querySelector('#splash-trailer').onclick=()=>{const id=slides[index].id;close();trailer(id)};overlay.querySelectorAll('[data-industry]').forEach(b=>b.onclick=()=>{index=+b.dataset.industry;draw()});draw();if(!reduced)timer=setInterval(()=>{index=(index+1)%slides.length;draw()},4500);setTimeout(close,reduced?11000:14500)
}

function albumsPage(){const languages=[...new Set(albums.map(a=>a.language))].sort();return `<section class="music-page"><div class="intro"><div><span class="eyebrow">Music across the years</span><h1>Albums & songs</h1></div><p><strong>${albums.length.toLocaleString()}</strong> releases · ${albums.filter(a=>a.songs?.length).length} playable previews</p></div><div class="filters music-filters"><label class="search">${icons.search}<input id="album-search" type="search" value="${esc(musicQuery)}" placeholder="Search albums, songs, artists…" aria-label="Search albums, songs and artists"></label><select id="album-language" aria-label="Music language"><option value="">All languages</option>${languages.map(x=>`<option ${x===musicLanguage?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="album-year" aria-label="Album year"><option value="">All years</option>${Array.from({length:new Date().getFullYear()-1999},(_,i)=>new Date().getFullYear()-i).map(x=>`<option ${String(x)===musicYear?'selected':''}>${x}</option>`).join('')}</select><label class="preview-filter"><input id="album-playable" type="checkbox" ${musicPlayable?'checked':''}><span>▶ Playable previews</span></label></div><div class="catalog-head"><div><h2>Explore the music catalog</h2><p>Verified videos play here; other releases open a precise YouTube search.</p></div><span class="count" id="album-count">${albumsLoaded?'':'Catalog loading…'}</span></div><div class="album-grid" id="album-grid"></div><div class="load-row" id="album-pages"></div></section>`}
function albumCard(a){const song=a.songs?.[0],playable=!!song,cover=a.cover||song?.thumbnail||'';return `<article class="album-card"><${playable?'button':'a'} class="album-cover ${playable?'':'album-cover-fallback'}" ${playable?`data-album-play="${a.id}" aria-label="Preview ${esc(a.title)}"`:`href="${esc(a.sourceUrl)}" target="_blank" rel="noopener" aria-label="Play or find ${esc(a.title)} on YouTube"`}><span class="album-art-title">${esc(a.title)}</span>${cover?`<img src="${esc(cover)}" alt="Cover for ${esc(a.title)}" loading="lazy" onerror="this.remove()">`:''}<span class="album-year">${a.year}${playable?' · Preview':''}</span><span class="album-play" aria-hidden="true">${playable?'▶':'↗'}</span></${playable?'button':'a'}><div class="album-copy"><span class="eyebrow">${esc(a.language)} music</span><h2>${playable?`<button data-album-play="${a.id}">${esc(a.title)}</button>`:`<a href="${esc(a.sourceUrl)}" target="_blank" rel="noopener">${esc(a.title)}</a>`}</h2><p>${esc(a.artist)}</p>${playable?`<button class="album-song" data-album-play="${a.id}"><span>▷</span><span><strong>${esc(song.title)}</strong><small>${esc(song.artist)}</small></span></button>`:`<a class="album-youtube-link" href="${esc(a.sourceUrl)}" target="_blank" rel="noopener" aria-label="Play or find ${esc(a.title)} on YouTube"><img src="logos/youtube.ico" alt="">Play on YouTube <span>↗</span></a>`}</div></article>`}
function filterAlbums(){if(!$('#album-grid'))return;const needle=searchText(musicQuery.trim());const list=albums.filter(a=>(!musicLanguage||a.language===musicLanguage)&&(!musicYear||a.year===+musicYear)&&(!musicPlayable||a.songs?.length)&&(!needle||searchText([a.title,a.artist,a.language,...(a.songs||[]).flatMap(s=>[s.title,s.artist])].join(' ')).includes(needle))).sort((a,b)=>Number(!!b.songs?.length)-Number(!!a.songs?.length)||b.year-a.year||a.title.localeCompare(b.title));const size=24,pages=Math.max(1,Math.ceil(list.length/size));musicPage=Math.min(Math.max(1,musicPage),pages);const start=(musicPage-1)*size;$('#album-count').textContent=`${list.length.toLocaleString()} album${list.length===1?'':'s'}`;$('#album-grid').innerHTML=list.length?list.slice(start,start+size).map(albumCard).join(''):`<div class="empty"><h3>No albums match.</h3><p>Try another artist, language, year, or preview filter.</p></div>`;$('#album-pages').innerHTML=list.length?`<div class="pagination"><span>Showing ${(start+1).toLocaleString()}–${Math.min(start+size,list.length).toLocaleString()} of ${list.length.toLocaleString()}</span><div class="page-controls"><button data-album-page="${musicPage-1}" ${musicPage===1?'disabled':''}>←</button><button class="current" aria-current="page">${musicPage} / ${pages}</button><button data-album-page="${musicPage+1}" ${musicPage===pages?'disabled':''}>→</button></div></div>`:'';document.querySelectorAll('[data-album-play]').forEach(b=>b.onclick=()=>playAlbum(b.dataset.albumPlay));document.querySelectorAll('[data-album-page]').forEach(b=>b.onclick=()=>{musicPage=+b.dataset.albumPage;filterAlbums();$('.music-page')?.scrollIntoView({behavior:'smooth'})})}
function playAlbum(id){const a=albums.find(x=>String(x.id)===String(id)),s=a?.songs?.[0];if(!s)return;show(`<div class="modal-header"><div><span class="eyebrow">${esc(a.language)} · ${a.year}</span><h2>${esc(s.title)}</h2><p>${esc(s.artist)} · ${esc(a.title)}</p></div><button class="close" aria-label="Close preview">×</button></div><iframe class="album-video" src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(s.youTubeVideoId)}?autoplay=1&rel=0" title="${esc(s.title)}" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe><p style="padding:0 22px 18px"><a href="https://www.youtube.com/watch?v=${encodeURIComponent(s.youTubeVideoId)}" target="_blank" rel="noopener">Open on YouTube ↗</a></p>`);$('#details').addEventListener('close',()=>{$('#details').innerHTML=''},{once:true})}
function bindAlbums(){if(page!=='albums')return;$('#album-search').oninput=e=>{musicQuery=e.target.value;musicPage=1;filterAlbums()};$('#album-language').onchange=e=>{musicLanguage=e.target.value;musicPage=1;filterAlbums()};$('#album-year').onchange=e=>{musicYear=e.target.value;musicPage=1;filterAlbums()};$('#album-playable').onchange=e=>{musicPlayable=e.target.checked;musicPage=1;filterAlbums()}}
function providerLogo(name){const n=name.toLowerCase();let p=platforms.find(p=>n.includes(p.name.toLowerCase()));if(!p&&/amazon|prime/.test(n))p=platforms.find(p=>p.key==='primevideo');if(!p&&/apple/.test(n))p=platforms.find(p=>p.key==='appletv');if(!p&&/hbo|max/.test(n))p=platforms.find(p=>p.key==='hbomax');if(!p&&/hotstar|jio/.test(n))p=platforms.find(p=>p.key==='jiohotstar');return p?.logo?`<img class="ott-logo" src="${esc(p.logo)}" alt="${esc(p.name)} logo" onerror="this.hidden=true">`:'<span class="provider-glyph" aria-hidden="true">▷</span>'}
function discover(){let html=extendedDiscover();const langs=[...new Set(movies.flatMap(m=>m.languages||[]))].sort();html=html.replace('<div class="sort">',`<select id="language-filter" aria-label="Original language"><option value="">All languages</option>${langs.map(l=>`<option ${l===language?'selected':''}>${esc(l)}</option>`).join('')}<option value="__unknown__" ${language==='__unknown__'?'selected':''}>Not indexed</option></select><div class="sort">`);const odia=['Dahaan','Pratikshya','DAMaN'].map(t=>movies.find(m=>m.title===t)).filter(Boolean);const odiaSection=page==='discover'?`<section class="odia-spotlight"><div class="odia-heading"><div><span class="eyebrow">A CLOSER LOOK · ODISHA</span><h2>Stories with a place to call home.</h2><p>Discover the voices, places and imagination of Odia cinema.</p></div><button class="secondary" id="explore-odia">Explore Odia cinema ↗</button></div><div class="odia-grid">${odia.map(m=>`<button class="odia-card" data-detail="${m.id}"><img src="${esc(m.poster)}" alt="" loading="lazy" onerror="this.hidden=true"><span class="odia-card-copy"><small>ODIA CINEMA · ${m.year}</small><strong>${esc(m.title)}</strong><span>Explore the film ↗</span></span></button>`).join('')}</div></section>`:'';html=html.replace('<section id="catalog">',odiaSection+'<section id="catalog">');html=html.replace('<section id="catalog">',`<section class="platform-discovery"><div><span class="eyebrow">Your stories. Your platforms.</span><p>Explore official services. Title links appear where sourced.</p></div><div class="platform-rail">${platforms.map(p=>`<a href="${esc(p.url)}" target="_blank" rel="noopener" title="Explore ${esc(p.name)} official catalog">${providerLogo(p.name)}<span>${esc(p.name)}</span>${p.free?'<small>Free catalog</small>':''}</a>`).join('')}</div></section><section id="catalog">`);return html}
function bindWatch(){document.querySelectorAll('[data-ask-watch]').forEach(b=>b.onclick=e=>{e.stopPropagation();if($('#details').open)$('#details').close();clayDot.where(+b.dataset.askWatch)})}
function bindHeroOnly(){document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{activeHero=+b.dataset.hero;redrawHero()});document.querySelectorAll('[data-hero-mode]').forEach(b=>b.onclick=()=>{heroMode=b.dataset.heroMode;activeHero=0;redrawHero()});$('#hero-next')?.addEventListener('click',()=>{activeHero=(activeHero+1)%heroTitles().length;redrawHero()});$('#hero-prev')?.addEventListener('click',()=>{activeHero=(activeHero+heroTitles().length-1)%heroTitles().length;redrawHero()});$('#hero-toggle')?.addEventListener('click',()=>{slidesPaused=!slidesPaused;redrawHero()})}
function redrawHero(){const hero=$('.hero-grid');if(!hero)return;hero.outerHTML=heroPanel();bindHeroOnly();bindCards()}
function bind(){baseExtendedBind();bindAlbums();$('#explore-odia')?.addEventListener('click',()=>{reset();language='Odia';render();scrollCatalog()});$('#language-filter')?.addEventListener('change',e=>{language=e.target.value;catalogPage=1;filter()});bindWatch();$('#hero-toggle')?.addEventListener('click',()=>{slidesPaused=!slidesPaused;redrawHero()})}
const originalBindCards=bindCards;bindCards=function(){originalBindCards();bindWatch()};
setInterval(()=>{if(slidesPaused||page!=='discover'||document.hidden||$('#details').open||clayDot?.isOpen()||window.matchMedia('(prefers-reduced-motion: reduce)').matches||document.querySelector('.hero-grid:hover')||document.activeElement?.matches('input,select,textarea'))return;const a=heroTitles();if(a.length>1){activeHero=(activeHero+1)%a.length;redrawHero()}},7000);
movies=movies.map(m=>read('cineclay.overrides',[]).find(o=>o.id===m.id&&o.source==='Manual')||m).filter(m=>!read('cineclay.removed',[]).includes(m.id));clayDot=createClayDot({getMovies:()=>movies,getRegion:()=>region,openDetail:detail,logo:providerLogo});if(location.hash==='#studio')page='admin';render();splash();

archivePromise.then(rows=>{const removed=new Set(read('cineclay.removed',[]));const ids=new Set(movies.map(m=>m.id));const overrides=new Map(read('cineclay.overrides',[]).filter(m=>m.source==='Manual').map(m=>[m.id,m]));original=[...original,...rows];movies=[...movies,...rows.filter(m=>!ids.has(m.id)&&!removed.has(m.id)).map(m=>overrides.get(m.id)||m)];archiveLoaded=true;if(page!=='admin')render();});
albumsPromise.then(rows=>{albums=rows;albumsLoaded=true;if(page==='albums')render()});
